package com.dreamcore.workspace.methods;
import com.dreamcore.workspace.identity.*;
import com.dreamcore.workspace.departure.DepartureAccess;
import com.dreamcore.workspace.governance.GovernanceAccess;
import com.dreamcore.workspace.material.MaterialAccess;
import com.dreamcore.workspace.evaluation.*;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;

/** Manual engineering maintenance and explicit scope adoption; not an autonomous evolution executor. */
@Service
public class MethodService {
 public record Version(UUID id,UUID familyId,int number,UUID baseVersion,MethodSelection.Configuration configuration,String configurationSha,String compatibility,String rationale,boolean published,Instant createdAt,boolean bodyAvailable) {}
 public record Family(UUID id,String kind,String title,int revision,UUID headVersion,UUID publishedVersion,List<Version> versions) {}
 public record Families(List<Family> items,boolean hasMore) {}
 public record RankingInput(List<MethodSelection.Candidate> items) {}
 public record Expected(List<UUID> items) {}
 public record CaseResult(UUID sampleVersion,List<UUID> expected,List<UUID> baseline,List<UUID> candidate,boolean baselinePass,boolean candidatePass) {}
 public record Comparison(UUID id,UUID candidateVersion,UUID baselineVersion,UUID standardVersion,List<UUID> sampleVersions,List<CaseResult> cases,int denominator,int baselinePass,int candidatePass,String conclusion,String validity,String mode,String businessQuality,Instant createdAt) {}
 public record Comparisons(List<Comparison> items,boolean hasMore) {}
 public record Adoption(UUID id,UUID tenantId,UUID workspaceId,int revision,String status,UUID versionId,String effectiveFallback,List<AdoptionEvent> history) {}
 public record AdoptionEvent(int revision,String action,UUID versionId,UUID actor,Instant createdAt) {}
 public record Selection(Adoption adoption,MethodSelection.MethodRef effective,MethodSelection.Configuration configuration,boolean canAdopt,Version adoptedVersion) {}
 public record Suite(EvaluationService.Asset standard,EvaluationService.Asset sample) {}
 private final JdbcTemplate db;private final IdentityService identities;private final GovernanceAccess governance;private final MaterialAccess access;private final EvaluationService evaluations;private final IdentityAudit audit;private final DepartureAccess departure;private final JsonMapper json=new JsonMapper();
 public MethodService(JdbcTemplate db,IdentityService identities,GovernanceAccess governance,MaterialAccess access,EvaluationService evaluations,IdentityAudit audit,DepartureAccess departure){this.db=db;this.identities=identities;this.governance=governance;this.access=access;this.evaluations=evaluations;this.audit=audit;this.departure=departure;}
 private String hash(Object... x){return IdentityService.hash(json.writeValueAsString(x));}
 @Transactional public Suite suite(UUID actor,UUID key,String title,RankingInput input,Expected expected){platform(actor);EvaluationService.text(title,180,true);if(input==null||expected==null)throw IdentityException.invalid();MethodSelection.candidates(input.items());if(input.items().isEmpty()||expected.items()==null||expected.items().size()!=input.items().size()||!new HashSet<>(expected.items()).equals(new HashSet<>(input.items().stream().map(MethodSelection.Candidate::id).toList())))throw IdentityException.invalid();UUID standardKey=UUID.nameUUIDFromBytes((key+":standard").getBytes(java.nio.charset.StandardCharsets.UTF_8));UUID sampleKey=UUID.nameUUIDFromBytes((key+":sample").getBytes(java.nio.charset.StandardCharsets.UTF_8));var criterion=new EvaluationService.Criterion("expected_order","FACT","REQUIRED","SYNTHETIC_EQUALS","在相同的合成候选集合中产生明确预期顺序，保持稳定排序和候选不增不减。");var standard=evaluations.create(actor,null,null,standardKey,"STANDARD",new EvaluationService.Content(title+" · 标准","REGRESSION","范围仅为本组合成排序样例；不代表模型能力或业务推荐效果。",List.of(criterion),"","","","真实企业内容价值未验证"),List.of());var sample=evaluations.create(actor,null,null,sampleKey,"SAMPLE",new EvaluationService.Content(title+" · 样例","REGRESSION","人工指定预期顺序，比较时程序实际执行两个方法。",List.of(),json.writeValueAsString(input),json.writeValueAsString(expected),"","非独立盲测；未覆盖真实用户反馈"),List.of());return new Suite(standard,sample);}
 private int num(Map<String,Object> r,String k){return ((Number)r.get(k)).intValue();}
 private IdentityException missing(){return new IdentityException(404,"METHOD_NOT_FOUND");}
 private void platform(UUID actor){identities.platform(actor);}
 private Version projection(UUID id){var rows=db.query("SELECT v.*,NOT v.scrubbed AND object_is_active('METHOD_VERSION',v.id) available,EXISTS(SELECT 1 FROM method_releases r WHERE r.version_id=v.id) released FROM method_versions v WHERE id=?",(r,n)->new Version(r.getObject("id",UUID.class),r.getObject("family_id",UUID.class),r.getInt("number"),r.getObject("base_version",UUID.class),r.getBoolean("available")?json.readValue(r.getString("configuration"),MethodSelection.Configuration.class):null,r.getString("configuration_sha"),r.getString("compatibility"),r.getBoolean("available")?r.getString("rationale"):"",r.getBoolean("released"),r.getTimestamp("created_at").toInstant(),r.getBoolean("available")),id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Version version(UUID id){var v=projection(id);if(!v.bodyAvailable())throw new IdentityException(404,"METHOD_VERSION_UNAVAILABLE");return v;}
 private void maintenanceLock(){db.queryForList("SELECT pg_advisory_xact_lock(72133001)");}
 private Family family(UUID id,boolean catalog){var rows=db.queryForList("SELECT * FROM method_families WHERE id=?",id);if(rows.isEmpty())throw missing();var r=rows.getFirst();var versions=db.queryForList("SELECT id FROM method_versions WHERE family_id=?"+(catalog?" AND NOT scrubbed AND object_is_active('METHOD_VERSION',id) AND EXISTS(SELECT 1 FROM method_releases r WHERE r.version_id=method_versions.id)":"")+" ORDER BY number DESC",UUID.class,id).stream().map(this::projection).toList();return new Family(id,(String)r.get("kind"),(String)r.get("title"),num(r,"revision"),catalog?null:(UUID)r.get("head_version"),(UUID)r.get("published_version"),versions);}
 @Transactional public Family get(UUID actor,UUID id){platform(actor);return family(id,false);}
 @Transactional public Families list(UUID actor,UUID tenant,int offset,int limit){EvaluationService.bounds(offset,limit);if(tenant==null)platform(actor);else identities.member(actor,tenant,false);var ids=db.queryForList("SELECT id FROM method_families"+(tenant==null?"":" WHERE published_version IS NOT NULL")+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",UUID.class,limit+1,offset);return new Families(ids.stream().limit(limit).map(id->family(id,tenant!=null)).toList(),ids.size()>limit);}
 private UUID append(UUID actor,UUID family,int number,UUID base,MethodSelection.Configuration configuration,String rationale){UUID id=UUID.randomUUID();db.update("INSERT INTO method_versions(id,family_id,number,base_version,configuration,configuration_sha,compatibility,rationale,created_by) VALUES (?,?,?,?,?::jsonb,?,'ranking-v1',?,?)",id,family,number,base,json.writeValueAsString(configuration),MethodSelection.configurationSha(configuration),rationale,actor);return id;}
 @Transactional public Family create(UUID actor,UUID key,String title,MethodSelection.Configuration configuration,String rationale){maintenanceLock();platform(actor);EvaluationService.text(title,180,true);EvaluationService.text(rationale,2000,true);MethodSelection.validate(configuration);String h=hash(title,configuration,rationale);UUID prior=identities.priorRequest(actor,key,"METHOD_CREATE",h);platform(actor);if(prior!=null)return family(prior,false);UUID id=UUID.randomUUID();db.update("INSERT INTO method_families(id,kind,title,created_by) VALUES (?,'RANKING_V1',?,?)",id,title,actor);UUID v=append(actor,id,1,null,configuration,rationale);db.update("UPDATE method_families SET head_version=? WHERE id=?",v,id);identities.remember(actor,key,"METHOD_CREATE",h,id);audit.record(actor,null,"METHOD_CREATE",id,"SUCCESS");return family(id,false);}
 @Transactional public Family candidate(UUID actor,UUID family,UUID key,int expected,MethodSelection.Configuration configuration,String rationale){maintenanceLock();platform(actor);MethodSelection.validate(configuration);EvaluationService.text(rationale,2000,true);String h=hash(family,expected,configuration,rationale);UUID prior=identities.priorRequest(actor,key,"METHOD_CANDIDATE",h);var rows=db.queryForList("SELECT * FROM method_families WHERE id=? FOR UPDATE",family);platform(actor);if(rows.isEmpty())throw missing();if(prior!=null)return family(family,false);var r=rows.getFirst();if(num(r,"revision")!=expected)throw new IdentityException(409,"METHOD_VERSION_CONFLICT");int number=db.queryForObject("SELECT max(number)+1 FROM method_versions WHERE family_id=?",Integer.class,family);UUID v=append(actor,family,number,(UUID)r.get("published_version"),configuration,rationale);db.update("UPDATE method_families SET head_version=?,revision=revision+1 WHERE id=?",v,family);identities.remember(actor,key,"METHOD_CANDIDATE",h,family);return family(family,false);}
 private boolean current(EvaluationService.Asset a){return a.status().equals("ACTIVE")&&a.revision()==a.version().revision();}
 private void standard(EvaluationService.Asset a){if(!a.kind().equals("STANDARD")||a.tenantId()!=null||!current(a)||a.version().content().criteria().isEmpty()||a.version().content().criteria().stream().anyMatch(c->!c.check().equals("SYNTHETIC_EQUALS")||!c.strength().equals("REQUIRED")))throw new IdentityException(409,"METHOD_STANDARD_NOT_SUPPORTED");}
 @Transactional public Comparison compare(UUID actor,UUID key,UUID candidate,UUID baseline,UUID standard,List<UUID> samples){maintenanceLock();
  platform(actor);if(samples==null||samples.isEmpty()||samples.size()>50||new HashSet<>(samples).size()!=samples.size())throw IdentityException.invalid();String h=hash(candidate,baseline,standard,samples);UUID prior=identities.priorRequest(actor,key,"METHOD_COMPARE",h);platform(actor);if(prior!=null)return comparison(actor,prior);Version v=version(candidate);if(!Objects.equals(v.baseVersion(),baseline))throw new IdentityException(409,"METHOD_BASELINE_CHANGED");MethodSelection.Configuration before=baseline==null?MethodSelection.DEFAULT:version(baseline).configuration();var s=evaluations.byVersion(actor,null,standard);standard(s);var origins=new HashSet<String>();var results=new ArrayList<CaseResult>();
  for(UUID id:samples){var a=evaluations.byVersion(actor,null,id);if(!current(a)||!a.kind().equals("SAMPLE")||!a.version().mode().equals("SYNTHETIC"))throw new IdentityException(409,"METHOD_SAMPLE_CHANGED");if(!origins.add(a.version().originKey()))throw new IdentityException(409,"EVALUATION_DUPLICATE_ORIGIN");RankingInput input;Expected expected;try{input=json.readValue(a.version().content().input(),RankingInput.class);expected=json.readValue(a.version().content().expected(),Expected.class);}catch(RuntimeException ex){throw new IdentityException(400,"METHOD_SAMPLE_FORMAT");}MethodSelection.candidates(input.items());if(input.items().isEmpty()||expected.items()==null||expected.items().size()!=input.items().size()||!new HashSet<>(expected.items()).equals(new HashSet<>(input.items().stream().map(MethodSelection.Candidate::id).toList())))throw new IdentityException(400,"METHOD_EXPECTED_ORDER_INVALID");var b=MethodSelection.order(input.items(),before);var c=MethodSelection.order(input.items(),v.configuration());results.add(new CaseResult(id,expected.items(),b,c,expected.items().equals(b),expected.items().equals(c)));}
  UUID id=UUID.randomUUID();db.update("INSERT INTO method_comparisons(id,candidate_version,baseline_version,standard_version,sample_versions,results,created_by) VALUES (?,?,?,?,?::jsonb,?::jsonb,?)",id,candidate,baseline,standard,json.writeValueAsString(new Expected(samples)),json.writeValueAsString(new Results(results)),actor);identities.remember(actor,key,"METHOD_COMPARE",h,id);return comparison(actor,id);
 }
 public record Results(List<CaseResult> items) {}
 @Transactional public Comparison comparison(UUID actor,UUID id){platform(actor);return comparisonInternal(actor,id);}
 private boolean evidenceCurrent(UUID actor,UUID version){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM evaluation_asset_versions v JOIN evaluation_assets a ON a.id=v.asset_id WHERE v.id=? AND a.tenant_id IS NULL AND a.status='ACTIVE' AND a.revision=v.revision AND NOT v.scrubbed AND object_is_active('EVALUATION_VERSION',v.id))",Boolean.class,version));}
 private Comparison comparisonInternal(UUID actor,UUID id){var rows=db.queryForList("SELECT * FROM method_comparisons WHERE id=?",id);if(rows.isEmpty())throw missing();var r=rows.getFirst();var samples=json.readValue(r.get("sample_versions").toString(),Expected.class).items();boolean methodBodies=projection((UUID)r.get("candidate_version")).bodyAvailable()&&(r.get("baseline_version")==null||projection((UUID)r.get("baseline_version")).bodyAvailable());boolean valid=methodBodies&&evidenceCurrent(actor,(UUID)r.get("standard_version"));for(UUID s:samples)valid&=evidenceCurrent(actor,s);var results=json.readValue(r.get("results").toString(),Results.class).items();int b=(int)results.stream().filter(CaseResult::baselinePass).count(),c=(int)results.stream().filter(CaseResult::candidatePass).count();boolean gains=results.stream().anyMatch(x->x.candidatePass()&&!x.baselinePass()),losses=results.stream().anyMatch(x->x.baselinePass()&&!x.candidatePass());String conclusion=gains&&losses?"TRADEOFF":losses?"REGRESSION":gains?"IMPROVED_ON_SAMPLES":"NO_CHANGE";return new Comparison(id,(UUID)r.get("candidate_version"),(UUID)r.get("baseline_version"),(UUID)r.get("standard_version"),samples,results,results.size(),b,c,conclusion,!methodBodies?"DETAILS_UNAVAILABLE":valid?"CURRENT":"STALE","SYNTHETIC","NOT_VALIDATED",((java.sql.Timestamp)r.get("created_at")).toInstant());}
 @Transactional public Comparisons comparisons(UUID actor,UUID family,int offset,int limit){platform(actor);EvaluationService.bounds(offset,limit);var ids=db.queryForList("SELECT c.id FROM method_comparisons c JOIN method_versions v ON v.id=c.candidate_version WHERE v.family_id=? ORDER BY c.created_at DESC,c.id LIMIT ? OFFSET ?",UUID.class,family,limit+1,offset);return new Comparisons(ids.stream().limit(limit).map(id->comparisonInternal(actor,id)).toList(),ids.size()>limit);}
 @Transactional public Family publish(UUID actor,UUID family,UUID key,int expected,UUID candidate,UUID comparison){maintenanceLock();
  platform(actor);String h=hash(family,expected,candidate,comparison);UUID prior=identities.priorRequest(actor,key,"METHOD_PUBLISH",h);var rows=db.queryForList("SELECT * FROM method_families WHERE id=? FOR UPDATE",family);platform(actor);if(rows.isEmpty())throw missing();if(prior!=null)return family(family,false);var r=rows.getFirst();Version v=version(candidate);if(num(r,"revision")!=expected||!candidate.equals(r.get("head_version"))||!Objects.equals(v.baseVersion(),r.get("published_version")))throw new IdentityException(409,"METHOD_VERSION_CONFLICT");
  var proof=comparisonInternal(actor,comparison);if(!proof.candidateVersion().equals(candidate)||!Objects.equals(proof.baselineVersion(),v.baseVersion())||!proof.validity().equals("CURRENT")||proof.candidatePass()!=proof.denominator()||proof.denominator()<1)throw new IdentityException(409,"METHOD_EVIDENCE_REQUIRED");
  // Block a concurrent standard/sample withdrawal between proof checking and release.
  var versionIds=new ArrayList<>(proof.sampleVersions());versionIds.add(proof.standardVersion());for(UUID id:versionIds.stream().sorted().toList())db.queryForList("SELECT a.id FROM evaluation_assets a JOIN evaluation_asset_versions v ON v.asset_id=a.id WHERE v.id=? FOR SHARE OF a",id);
  proof=comparisonInternal(actor,comparison);if(!proof.validity().equals("CURRENT"))throw new IdentityException(409,"METHOD_EVIDENCE_CHANGED");
  db.update("INSERT INTO method_releases(version_id,comparison_id,actor_id) VALUES (?,?,?)",candidate,comparison,actor);db.update("UPDATE method_families SET published_version=?,revision=revision+1 WHERE id=?",candidate,family);identities.remember(actor,key,"METHOD_PUBLISH",h,family);audit.record(actor,null,"METHOD_PUBLISH",candidate,"SUCCESS");return family(family,false);
 }
 private void scope(UUID actor,UUID tenant,UUID workspace,boolean write){identities.member(actor,tenant,false);if(write)departure.requireActiveBusiness(actor,tenant);if(workspace!=null){var s=access.require(actor,tenant,workspace,false);if(write&&!s.kind().equals("PERSONAL"))governance.require(actor,tenant,GovernanceAccess.Capability.METHOD_ADOPT,workspace);}else if(write)governance.require(actor,tenant,GovernanceAccess.Capability.METHOD_ADOPT,null);}
 private Adoption adoption(UUID tenant,UUID workspace){var rows=db.queryForList("SELECT * FROM method_adoptions WHERE tenant_id=? AND workspace_id IS NOT DISTINCT FROM ?::uuid",tenant,workspace);if(rows.isEmpty())return null;var r=rows.getFirst();UUID id=(UUID)r.get("id");var history=db.query("SELECT * FROM method_adoption_events WHERE adoption_id=? ORDER BY revision",(e,n)->new AdoptionEvent(e.getInt("revision"),e.getString("action"),e.getObject("version_id",UUID.class),e.getObject("actor_id",UUID.class),e.getTimestamp("created_at").toInstant()),id);return new Adoption(id,tenant,workspace,num(r,"revision"),(String)r.get("status"),(UUID)r.get("version_id"),workspace==null?"BUILTIN":"TENANT_THEN_BUILTIN",history);}
 private boolean releaseApplicable(UUID version){if(!projection(version).bodyAvailable())return false;return Boolean.TRUE.equals(db.queryForObject("""
  SELECT EXISTS(SELECT 1 FROM method_releases r JOIN method_comparisons c ON c.id=r.comparison_id
   JOIN evaluation_asset_versions sv ON sv.id=c.standard_version JOIN evaluation_assets sa ON sa.id=sv.asset_id
   WHERE r.version_id=? AND sa.status='ACTIVE' AND sa.revision=sv.revision AND NOT sv.scrubbed AND object_is_active('EVALUATION_VERSION',sv.id)
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(c.sample_versions->'items') x
    LEFT JOIN evaluation_asset_versions v ON v.id=x.value::uuid LEFT JOIN evaluation_assets a ON a.id=v.asset_id
    WHERE v.id IS NULL OR v.scrubbed OR NOT object_is_active('EVALUATION_VERSION',v.id) OR a.status<>'ACTIVE' OR a.revision<>v.revision))
  """,Boolean.class,version));}
 @Transactional public Selection selection(UUID actor,UUID tenant,UUID workspace){scope(actor,tenant,workspace,false);boolean canAdopt=true;try{scope(actor,tenant,workspace,true);}catch(IdentityException ex){if(ex.status!=403&&!ex.code.equals("DEPARTURE_BUSINESS_STOPPED"))throw ex;canAdopt=false;}var a=adoption(tenant,workspace);var effective=a;if((effective==null||!effective.status().equals("ACTIVE"))&&workspace!=null)effective=adoption(tenant,null);if(effective==null||!effective.status().equals("ACTIVE"))return new Selection(a,new MethodSelection.MethodRef(null,0,"BUILTIN",null,MethodSelection.configurationSha(MethodSelection.DEFAULT)),MethodSelection.DEFAULT,canAdopt,a==null?null:projection(a.versionId()));var v=version(effective.versionId());return new Selection(a,new MethodSelection.MethodRef(v.id(),effective.revision(),effective.workspaceId()==null?"TENANT":"WORKSPACE",effective.workspaceId(),v.configurationSha()),v.configuration(),canAdopt,a==null?null:projection(a.versionId()));}
 @Transactional public Selection adopt(UUID actor,UUID tenant,UUID workspace,UUID key,int expected,String action,UUID version,boolean limitationsAccepted){
  identities.member(actor,tenant,false,false);if(action==null||!Set.of("ADOPT","STOP","ROLLBACK").contains(action)||expected<0)throw IdentityException.invalid();String h=hash(tenant,workspace,expected,action,version,limitationsAccepted);UUID prior=identities.priorRequest(actor,key,"METHOD_ADOPT",h);
  db.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE",tenant);scope(actor,tenant,workspace,true);maintenanceLock();if(prior!=null)return selection(actor,tenant,workspace);var a=adoption(tenant,workspace);if((a==null?0:a.revision())!=expected)throw new IdentityException(409,"METHOD_ADOPTION_CHANGED");
  if(action.equals("STOP")){if(a==null||!a.status().equals("ACTIVE")||!Objects.equals(a.versionId(),version))throw new IdentityException(409,"METHOD_ADOPTION_CHANGED");}
  else{if(!limitationsAccepted)throw new IdentityException(400,"METHOD_LIMITATIONS_NOT_ACCEPTED");Version v=version(version);if(!v.published()||!v.compatibility().equals("ranking-v1"))throw new IdentityException(409,"METHOD_NOT_RELEASED");db.queryForList("SELECT a.id FROM method_releases r JOIN method_comparisons c ON c.id=r.comparison_id JOIN evaluation_asset_versions v ON v.id=c.standard_version OR v.id IN(SELECT x.value::uuid FROM jsonb_array_elements_text(c.sample_versions->'items') x) JOIN evaluation_assets a ON a.id=v.asset_id WHERE r.version_id=? ORDER BY a.id FOR SHARE OF a",version);if(!releaseApplicable(version))throw new IdentityException(409,"METHOD_EVIDENCE_CHANGED");if(action.equals("ROLLBACK")&&(a==null||a.history().stream().noneMatch(e->!e.action().equals("STOP")&&e.versionId().equals(version))))throw new IdentityException(409,"METHOD_ROLLBACK_UNAVAILABLE");}
  UUID id=a==null?UUID.randomUUID():a.id();int rev=expected+1;String status=action.equals("STOP")?"STOPPED":"ACTIVE";if(a==null)db.update("INSERT INTO method_adoptions(id,tenant_id,workspace_id,status,version_id,actor_id) VALUES (?,?,?,?,?,?)",id,tenant,workspace,status,version,actor);else db.update("UPDATE method_adoptions SET revision=?,status=?,version_id=?,actor_id=?,updated_at=now() WHERE id=?",rev,status,version,actor,id);
  db.update("INSERT INTO method_adoption_events(id,adoption_id,revision,action,version_id,actor_id) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),id,rev,action,version,actor);identities.remember(actor,key,"METHOD_ADOPT",h,id);audit.record(actor,tenant,"METHOD_"+action,id,"SUCCESS");return selection(actor,tenant,workspace);
 }
}
